{
  "name": "opencode-bg-control",
  "version": "0.1.1",
  "description": "Safe, bounded OpenCode tools for inspecting and cancelling background Task subagents",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "background-tasks",
    "subagents",
    "agent-tools"
  ],
  "author": "DKotsyuba",
  "license": "MIT",
  "type": "module",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/DKotsyuba/opencode-bg-control.git"
  },
  "bugs": {
    "url": "https://github.com/DKotsyuba/opencode-bg-control/issues"
  },
  "homepage": "https://github.com/DKotsyuba/opencode-bg-control#readme",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist",
    "README.md",
    "LICENSE",
    "AGENTS.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "clean": "rm -rf dist",
    "build:js": "bun build index.ts --outdir dist --target bun --format esm --external @opencode-ai/plugin",
    "build:types": "tsc -p tsconfig.build.json && rm -rf dist/src",
    "build": "npm run clean && npm run build:js && npm run build:types",
    "typecheck": "tsc -p tsconfig.json --noEmit",
    "test": "bun test",
    "test:performance": "bun test test/performance.test.ts",
    "prepack": "npm run typecheck && npm test && npm run test:performance && npm run build"
  },
  "dependencies": {
    "@opencode-ai/plugin": "1.18.5"
  },
  "devDependencies": {
    "typescript": "5.9.3"
  }
}
